"""World news, Tuesday 24 November 2026, in one image.

Entry for the make.fun competition news-image-20261124.
Running this program writes a single editorial front-page poster to
``<MAKEFUN_OUTPUT_DIR>/entry.png`` (default ``/output/entry.png``)
summing up the six biggest world-news stories of Tuesday 24 November
2026, as reported that day:

  1. SPACE   -- Russia's "Sputnik-S": Western intelligence warns a
     satellite built to carry a nuclear warhead could launch as soon
     as December; NATO vows to defend space.
  2. UKRAINE -- Russian strikes on the Kyiv region kill at least 14;
     hacked data puts Moscow's war dead near 500,000.
  3. LIBYA   -- Ukraine sinks the Russian corvette Merkury at
     Benghazi with sea drones; the war spreads beyond Europe.
  4. TECH    -- Nvidia reinstates Jensen Huang as CEO after Trump
     intervened; Vance joins the board as emissary.
  5. ENERGY  -- Iran vows to use "all its tools" against the US naval
     blockade, days after the Strait of Hormuz tanker strikes.
  6. ASIA    -- Indonesia confirms 24 dead in the Cikande candy
     factory fire; about 30 workers still missing.

The poster below is embedded as base64 PNG data, so the run is fully
deterministic and needs no network, no fonts and no installed
packages: Python 3.13 standard library only. The poster itself was
typeset programmatically (PIL + DejaVu/Liberation fonts) from a
text-free flat illustration, so every headline is spelled correctly.

Run:  python3 main.py
       (MAKEFUN_OUTPUT_DIR stands in for /output outside the grader.)
"""

import base64
import hashlib
import os
import sys
from pathlib import Path

# The poster, as a base64 PNG. One line: the image bytes, nothing else.
POSTER_B64 = ""

PNG_MAGIC = b"\x89PNG\r\n\x1a\n"

# sha256 of the poster this program must reproduce, byte for byte.
EXPECTED_SHA256 = (
    "19a60c4de019fb6dc2933d50b00438745e69dddad733516b175356fed104801b"
)


def main() -> int:
    out_dir = Path(os.environ.get("MAKEFUN_OUTPUT_DIR", "/output"))
    out_dir.mkdir(parents=True, exist_ok=True)
    out_path = out_dir / "entry.png"

    raw = base64.b64decode(POSTER_B64, validate=True)
    if not raw.startswith(PNG_MAGIC):
        print("error: embedded data is not a PNG", file=sys.stderr)
        return 1
    out_path.write_bytes(raw)

    digest = hashlib.sha256(raw).hexdigest()
    if digest != EXPECTED_SHA256:
        print(f"error: sha256 mismatch: got {digest}", file=sys.stderr)
        return 1
    print(f"wrote {out_path} {len(raw)} bytes sha256={digest}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
